<template>
  <view class="page"><jk-page-nav title="销售详情"/><view class="content"><view class="status-card"><jk-status-tag :text="statusText" :tone="tone"/><strong>¥{{money(data.totalAmount)}}</strong><text>{{data.saleNo}}</text><small>{{statusHint}}</small></view><view class="card"><view class="title">成交信息</view><view class="line"><text>客户类型</text><text>{{data.customerType}}</text></view><view class="line"><text>客户</text><text>{{data.customerNameMasked||'未留存'}} {{data.customerPhoneMasked||''}}</text></view><view class="line"><text>销售时间</text><text>{{data.saleTime}}</text></view><view class="line"><text>收款方式</text><text>{{data.paymentMethod||'--'}}</text></view><view class="line"><text>实名客户</text><text>{{data.registeredCustomer?'是':'否'}}</text></view></view><view class="card"><view class="title">商品与经营成本</view><view v-for="item in data.items||[]" :key="item.id" class="item"><view><text>{{item.productName}}</text><text>{{item.skuName||item.skuCode||'单规格'}} × {{item.quantity}}</text></view><view><strong>¥{{money(item.totalAmount)}}</strong><text>成本 ¥{{money(item.costAmount)}} · 毛利 ¥{{money(item.profitAmount)}}</text></view></view></view><view class="card"><view class="title">处理记录</view><view v-for="log in data.auditLogs||[]" :key="log.id" class="log"><text>{{log.action}}</text><text>{{log.remark||log.afterStatus}}</text><small>{{log.createTime}}</small></view></view><button v-if="canCancel" class="secondary" @tap="cancel">取消销售单</button><button v-if="canReturn" class="secondary danger" @tap="returnAll">整单退货</button></view></view>
</template>
<script>
import JkPageNav from '@/components/jk/jk-page-nav.vue';import JkStatusTag from '@/components/jk/jk-status-tag.vue';import{getJkOfflineSaleDetail,cancelJkOfflineSale,returnJkOfflineSale}from'@/api/jkV31.js';
export default{components:{JkPageNav,JkStatusTag},data(){return{id:null,data:{}}},computed:{statusText(){const m={PENDING_AUDIT:'待后台审核',CONFIRMED:'已确认',AUDIT_REJECTED:'审核驳回',CANCELLED:'已取消',PARTIALLY_RETURNED:'部分退货',RETURNED:'已退货'};return m[this.data.status]||this.data.status||'处理中'},tone(){return this.data.status==='CONFIRMED'?'success':this.data.status==='PENDING_AUDIT'?'warning':['AUDIT_REJECTED','CANCELLED','RETURNED'].includes(this.data.status)?'danger':'info'},statusHint(){return this.data.status==='PENDING_AUDIT'?'审核通过前不会扣减库存、生成业绩或佣金':this.data.status==='CONFIRMED'?'库存、业绩和经营收益已按成交快照确认':'历史快照不会因关系或规则变化而改写'},canCancel(){return['PENDING_AUDIT','AUDIT_REJECTED','CREATED'].includes(this.data.status)},canReturn(){return['CONFIRMED','PARTIALLY_RETURNED'].includes(this.data.status)}},onLoad(o){this.id=o.id},onShow(){this.load()},methods:{money(v){return Number(v||0).toFixed(2)},load(){getJkOfflineSaleDetail(this.id).then(r=>{this.data=(r&&r.data)||r||{}})},cancel(){uni.showModal({title:'取消销售单',editable:true,placeholderText:'请输入取消原因',success:r=>{if(r.confirm)cancelJkOfflineSale(this.id,r.content||'用户取消').then(()=>{uni.showToast({title:'已取消'});this.load()})}})},returnAll(){const items=(this.data.items||[]).filter(x=>Number(x.returnedQty||0)<Number(x.quantity||0)).map(x=>({saleItemId:x.id,quantity:Number(x.quantity||0)-Number(x.returnedQty||0)}));if(!items.length)return uni.showToast({title:'没有可退商品',icon:'none'});uni.showModal({title:'确认整单退货',content:'退货会回补库存，并按比例冲减业绩、经营收益和平台佣金。',success:r=>{if(r.confirm)returnJkOfflineSale(this.id,{requestNo:'OSR-'+Date.now(),reason:'用户整单退货',items}).then(()=>{uni.showToast({title:'退货完成'});this.load()})}})}}}
</script>
<style scoped>.page{min-height:100vh;background:#f7f9f9}.content{padding:18rpx 22rpx 44rpx}.status-card{display:flex;flex-direction:column;align-items:center;padding:30rpx;border-radius:22rpx;background:#fff}.status-card strong{margin-top:18rpx;color:#10a981;font-size:48rpx}.status-card>text{margin-top:8rpx;color:#59666b;font-size:23rpx}.status-card small{margin-top:12rpx;color:#90999d;font-size:20rpx;text-align:center}.card{margin-top:18rpx;padding:24rpx;border-radius:20rpx;background:#fff}.title{margin-bottom:12rpx;font-size:27rpx;font-weight:700}.line{display:flex;justify-content:space-between;padding:15rpx 0;border-bottom:1rpx solid #edf1f0;color:#7c878c;font-size:22rpx}.line text:last-child{color:#3d4a50}.item{display:flex;justify-content:space-between;padding:18rpx 0;border-bottom:1rpx solid #edf1f0}.item view text{display:block}.item view:first-child text:first-child{font-size:24rpx;font-weight:700}.item view:first-child text:last-child,.item view:last-child text{margin-top:6rpx;color:#899398;font-size:20rpx}.item view:last-child{text-align:right}.item strong{color:#273238;font-size:25rpx}.log{padding:16rpx 0;border-bottom:1rpx solid #edf1f0}.log text,.log small{display:block}.log text:first-child{font-size:23rpx;font-weight:700}.log text:nth-child(2){margin-top:5rpx;color:#69757a;font-size:21rpx}.log small{margin-top:5rpx;color:#a0a9ad;font-size:19rpx}.secondary{height:78rpx;margin-top:18rpx;border:1rpx solid #dce4e2;border-radius:39rpx;background:#fff;color:#526066;font-size:24rpx;line-height:78rpx}.secondary::after{border:0}.secondary.danger{color:#d95454}</style>
